<?php /** @var array $package @var ?array $menuGroup @var string $basePath */ ?>
<section class="c-package-detail-hero"><div><a class="c-back-link" href="<?= e_attr($basePath) ?>/packages">← All packages</a><p class="c-eyebrow c-eyebrow-light"><?= e($package['eyebrow']) ?></p><h1><?= e($package['name']) ?></h1><p><?= e($package['description']) ?></p><div class="c-package-hero-price">From $<?= e(number_format(((int) $package['price_cents']) / 100, 0)) ?> <small><?= e($package['price_note']) ?></small></div></div></section>
<section class="c-wrap c-section c-package-detail-grid"><div><p class="c-eyebrow">What’s included</p><h2>A generous foundation for your event</h2><ul class="c-check-list"><?php foreach (preg_split('/\r?\n/', (string) $package['inclusions']) as $line): if (trim($line) === '') continue; ?><li><?= e(trim($line)) ?></li><?php endforeach; ?></ul><?php $rules = json_decode((string) $package['choice_rules'], true) ?: []; if ($rules !== []): ?><h3>Your included menu choices</h3><ul class="c-check-list"><?php foreach ($rules as $rule): ?><li><?= e($rule['label']) ?>: choose <?= (int) $rule['min'] ?>–<?= (int) $rule['max'] ?> dishes</li><?php endforeach; ?></ul><p>These selections are included in the package price.</p><?php endif; ?><?php if ($menuGroup !== null): ?><h3><?= e($menuGroup['name']) ?></h3><?php if ($menuGroup['description']): ?><p><?= e($menuGroup['description']) ?></p><?php endif; ?><ul class="c-check-list"><?php foreach ($menuGroup['items'] as $item): ?><li><?= e($item['name']) ?></li><?php endforeach; ?></ul><?php endif; ?></div><aside><p class="c-eyebrow">At a glance</p><dl><div><dt>Guest range</dt><dd><?= (int) $package['guest_min'] ?><?= $package['guest_max'] ? '–' . (int) $package['guest_max'] : '+' ?></dd></div><div><dt>Starting price</dt><dd>$<?= e(number_format(((int) $package['price_cents']) / 100, 0)) ?></dd></div><div><dt>Customization</dt><dd>Available</dd></div></dl><a class="c-button c-button-green" href="<?= e_attr($basePath) ?>/request-a-quote&amp;package=<?= e_attr(rawurlencode($package['slug'])) ?>">Build my proposal</a></aside></section>
